1	// Helpers shared by the POST /api/bookings tests.
2	import fs from 'node:fs';
3	import path from 'node:path';
4	import assert from 'node:assert/strict';
5	import { startServer, makeTempDir, request, postBooking, booking, JSON_CT } from './server.mjs';
6	
7	export const CT_JSON = { 'Content-Type': 'application/json' };
8	export const BOOKING_KEYS = ['date', 'end', 'id', 'room', 'start', 'title'];
9	
10	/** Starts a server with its own temp data file; returns { port, close }. */
11	export async function setup() {
12	  const dir = makeTempDir();
13	  const srv = await startServer({ env: { DATA_FILE: path.join(dir, 'data.json') } });
14	  return {
15	    port: srv.port,
16	    close: async () => {
17	      await srv.stop();
18	      fs.rmSync(dir, { recursive: true, force: true });
19	    },
20	  };
21	}
22	
23	let dateCounter = 0;
24	/** A new valid date on every call, so bookings of different tests never overlap. */
25	export function nextDate() {
26	  dateCounter += 1;
27	  return new Date(Date.UTC(2030, 0, 1 + dateCounter)).toISOString().slice(0, 10);
28	}
29	
30	/** A valid booking body on a date no other call has used. */
31	export function freshBooking(overrides = {}) {
32	  return booking({ date: nextDate(), ...overrides });
33	}
34	
35	export function assertError(res, status, message) {
36	  assert.equal(res.status, status);
37	  assert.deepEqual(res.json, { error: message });
38	  assert.equal(res.headers['content-type'], JSON_CT);
39	}
40	
41	/** Asserts a 201 reply whose body is the sent booking (minus nothing) plus an id. */
42	export function assertCreated(res, sent, expectedOverrides = {}) {
43	  assert.equal(res.status, 201);
44	  assert.equal(res.headers['content-type'], JSON_CT);
45	  assert.equal(typeof res.json.id, 'number');
46	  const { id, ...rest } = res.json;
47	  assert.deepEqual(Object.keys(res.json).sort(), BOOKING_KEYS);
48	  const { room, title, date, start, end } = { ...sent, ...expectedOverrides };
49	  assert.deepEqual(rest, { room, title, date, start, end });
50	  return id;
51	}
52	
53	/** POSTs raw body (string or Buffer) with the given headers. */
54	export function postRaw(port, body, headers = CT_JSON) {
55	  return request(port, { method: 'POST', target: '/api/bookings', headers, body });
56	}
57	
58	/** JSON of `obj` padded with trailing spaces to exactly `bytes` bytes. */
59	export function paddedBody(obj, bytes) {
60	  const json = JSON.stringify(obj);
61	  const pad = bytes - Buffer.byteLength(json);
62	  assert.ok(pad >= 0, 'object larger than requested size');
63	  return json + ' '.repeat(pad);
64	}
65	
66	export { request, postBooking, booking, JSON_CT };
