1	// POST /api/bookings: booking rules 4 to 10 (fields, order of rules, overlaps).
2	import { describe, test, before, after } from 'node:test';
3	import assert from 'node:assert/strict';
4	import {
5	  setup, freshBooking, nextDate, assertError, assertCreated, postBooking, postRaw,
6	} from './helpers/booking-utils.mjs';
7	
8	const ROOM_MSG = 'room must be one of Aurora, Borealis, Cosmos';
9	const TITLE_MSG = 'title must be 1 to 80 characters';
10	const DATE_MSG = 'date must be a valid YYYY-MM-DD date';
11	const START_MSG = 'start must be HH:MM';
12	const END_MSG = 'end must be HH:MM';
13	const ORDER_MSG = 'end must be after start';
14	
15	let env;
16	before(async () => { env = await setup(); });
17	after(async () => { await env.close(); });
18	
19	/** One test per value: `field` set to `value` (undefined means missing) must give 400 `message`. */
20	function rejectCases(field, values, message) {
21	  for (const value of values) {
22	    const label = value === undefined ? 'missing' : JSON.stringify(value);
23	    test(`${field} ${label.length > 40 ? `${label.slice(0, 40)}...` : label} is rejected`, async () => {
24	      const res = await postBooking(env.port, freshBooking({ [field]: value }));
25	      assertError(res, 400, message);
26	    });
27	  }
28	}
29	
30	/** One test per [value, stored]: `field` set to `value` must give 201. */
31	function acceptCases(field, cases) {
32	  for (const [value, stored = value] of cases) {
33	    test(`${field} ${JSON.stringify(value).slice(0, 40)} is accepted`, async () => {
34	      const sent = freshBooking({ [field]: value });
35	      const res = await postBooking(env.port, sent);
36	      assertCreated(res, sent, { [field]: stored });
37	    });
38	  }
39	}
40	
41	describe('rule 4: room', () => {
42	  rejectCases('room', ['aurora', 'AURORA', ' Aurora', 'Aurora ', '', undefined, null, 1, ['Aurora'], 'Dawn'], ROOM_MSG);
43	  acceptCases('room', [['Aurora'], ['Borealis'], ['Cosmos']]);
44	});
45	
46	describe('rule 5: title', () => {
47	  rejectCases('title', [undefined, null, 5, '', '   ', '\t\n', 'a'.repeat(81), ` ${'a'.repeat(81)} `,
48	    '😀'.repeat(41), 'é'.repeat(81), ['x'], {}], TITLE_MSG);
49	  acceptCases('title', [
50	    ['a'.repeat(80)],
51	    [`  ${'a'.repeat(80)}  `, 'a'.repeat(80)],
52	    [' X ', 'X'],
53	    [' X ', 'X'],
54	    ['﻿X', 'X'],
55	    ['\t\nX\r\n', 'X'],
56	    ['  two  words  ', 'two  words'],
57	    ['😀'.repeat(40)],
58	    ['é'.repeat(80)],
59	    ['<b>x</b>'],
60	  ]);
61	});
62	
63	describe('rule 6: date', () => {
64	  rejectCases('date', ['2100-02-29', '2001-02-29', '1999-12-31', '2100-01-01', '2026-04-31', '2026-13-01',
65	    '2026-00-10', '2026-01-00', '2026-01-32', ' 2026-11-03', '2026-11-03 ', '2026-11-3', '26-11-03',
66	    '2026/11/03', '20261103', '２０２６-11-03', '2026-11-03T00:00', 20261103, null, undefined, ''], DATE_MSG);
67	  acceptCases('date', [['2000-02-29'], ['2096-02-29'], ['2004-02-29'], ['2000-01-01'], ['2099-12-31'],
68	    ['2026-04-30']]);
69	});
70	
71	describe('rule 7: start', () => {
72	  rejectCases('start', ['24:00', '9:00', '09:0', '09:60', '0900', '09.00', ' 09:00', '09:00 ', '09:00:00',
73	    '-1:00', '٠٩:٠٠', 900, null, undefined, ''], START_MSG);
74	  test('00:00 to 00:01 is accepted', async () => {
75	    const sent = freshBooking({ start: '00:00', end: '00:01' });
76	    assertCreated(await postBooking(env.port, sent), sent);
77	  });
78	  test('23:58 to 23:59 is accepted', async () => {
79	    const sent = freshBooking({ start: '23:58', end: '23:59' });
80	    assertCreated(await postBooking(env.port, sent), sent);
81	  });
82	});
83	
84	describe('rule 8: end', () => {
85	  rejectCases('end', ['24:00', '9:00', '23:60', '10:00 ', '10.00', 1000, null, undefined, ''], END_MSG);
86	});
87	
88	describe('rule 9: end after start', () => {
89	  test('end equal to start is rejected', async () => {
90	    assertError(await postBooking(env.port, freshBooking({ start: '09:00', end: '09:00' })), 400, ORDER_MSG);
91	  });
92	  test('end before start is rejected', async () => {
93	    assertError(await postBooking(env.port, freshBooking({ start: '10:00', end: '09:00' })), 400, ORDER_MSG);
94	  });
95	});
96	
97	describe('order of rules: the first failing rule wins', () => {
98	  const bad = { room: 'Dawn', title: '', date: 'x', start: 'x', end: 'x' };
99	  const cases = [
100	    ['empty object gives the room error', null, ROOM_MSG],
101	    ['bad room and bad title: room', bad, ROOM_MSG],
102	    ['good room, bad title, date, start, end: title', { ...bad, room: 'Aurora' }, TITLE_MSG],
103	    ['good room and title, bad date, start, end: date', { ...bad, room: 'Aurora', title: 'T' }, DATE_MSG],
104	    ['good up to date, bad start and end: start', { ...bad, room: 'Aurora', title: 'T', date: '2030-01-01' }, START_MSG],
105	    ['good up to start, bad end: end', { ...bad, room: 'Aurora', title: 'T', date: '2030-01-01', start: '09:00' }, END_MSG],
106	    ['all valid but end before start: order', { room: 'Aurora', title: 'T', date: '2030-01-01', start: '10:00', end: '09:00' }, ORDER_MSG],
107	  ];
108	  for (const [name, body, message] of cases) {
109	    test(name, async () => {
110	      const res = body === null ? await postRaw(env.port, '{}') : await postBooking(env.port, body);
111	      assertError(res, 400, message);
112	    });
113	  }
114	
115	  test('rule 9 comes before rule 10', async () => {
116	    const date = nextDate();
117	    const first = await postBooking(env.port, freshBooking({ date, start: '09:00', end: '10:00' }));
118	    assert.equal(first.status, 201);
119	    const res = await postBooking(env.port, freshBooking({ date, start: '09:30', end: '09:30' }));
120	    assertError(res, 400, ORDER_MSG);
121	  });
122	});
123	
124	describe('rule 10: overlaps', () => {
125	  const at = (date, start, end, room = 'Aurora') => freshBooking({ date, start, end, room });
126	  const conflict = (start, end) => `room is already booked from ${start} to ${end}`;
127	
128	  test('overlapping starts, ends, adjacency before and after', async () => {
129	    const date = nextDate();
130	    assert.equal((await postBooking(env.port, at(date, '09:00', '10:00'))).status, 201);
131	    assertError(await postBooking(env.port, at(date, '09:30', '10:30')), 409, conflict('09:00', '10:00'));
132	    assertError(await postBooking(env.port, at(date, '08:00', '09:01')), 409, conflict('09:00', '10:00'));
133	    assert.equal((await postBooking(env.port, at(date, '10:00', '11:00'))).status, 201);
134	    assert.equal((await postBooking(env.port, at(date, '08:00', '09:00'))).status, 201);
135	  });
136	
137	  test('same times in another room or on another date are fine', async () => {
138	    const date = nextDate();
139	    assert.equal((await postBooking(env.port, at(date, '09:00', '10:00'))).status, 201);
140	    assert.equal((await postBooking(env.port, at(date, '09:00', '10:00', 'Borealis'))).status, 201);
141	    assert.equal((await postBooking(env.port, at(nextDate(), '09:00', '10:00'))).status, 201);
142	  });
143	
144	  test('reports the overlapping booking that starts earliest, not the first created', async () => {
145	    const date = nextDate();
146	    assert.equal((await postBooking(env.port, at(date, '10:00', '11:00'))).status, 201);
147	    assert.equal((await postBooking(env.port, at(date, '08:00', '09:00'))).status, 201);
148	    assertError(await postBooking(env.port, at(date, '08:30', '10:30')), 409, conflict('08:00', '09:00'));
149	  });
150	
151	  test('a booking containing an existing one conflicts with it', async () => {
152	    const date = nextDate();
153	    assert.equal((await postBooking(env.port, at(date, '09:00', '10:00'))).status, 201);
154	    assertError(await postBooking(env.port, at(date, '08:00', '11:00')), 409, conflict('09:00', '10:00'));
155	  });
156	
157	  test('a booking inside an existing one conflicts with it', async () => {
158	    const date = nextDate();
159	    assert.equal((await postBooking(env.port, at(date, '09:00', '12:00'))).status, 201);
160	    assertError(await postBooking(env.port, at(date, '10:00', '11:00')), 409, conflict('09:00', '12:00'));
161	  });
162	
163	  test('an identical booking conflicts', async () => {
