157	function sendChunked(port, headers, chunkCount, chunkSize) {
158	  return new Promise((resolve, reject) => {
159	    const req = http.request({ host: '127.0.0.1', port, method: 'POST', path: '/api/bookings', headers, agent: false });
160	    req.on('error', reject);
161	    req.on('response', (res) => {
162	      const parts = [];
163	      res.on('data', (c) => parts.push(c));
164	      res.on('end', () => resolve({ status: res.statusCode, json: JSON.parse(Buffer.concat(parts).toString('utf8')) }));
165	    });
166	    const chunks = Array.from({ length: chunkCount }, () => Buffer.alloc(chunkSize, 0x61));
167	    Readable.from(chunks).pipe(req);
168	  });
169	}
