130	async function startServerOn3000(t, value, cwd) {
131	  const { spawn } = await import('node:child_process');
132	  const env = { ...process.env, ...(value === undefined ? {} : { PORT: value }) };
133	  if (value === undefined) delete env.PORT;
134	  delete env.DATA_FILE;
135	  const child = spawn(process.execPath, [path.join(ROOT, 'server.mjs')], { cwd, env, stdio: ['ignore', 'pipe', 'pipe'] });
136	  const closed = new Promise((resolve) => child.on('close', resolve));
137	  t.after(async () => { child.kill('SIGKILL'); await closed; });
138	  let stdout = '';
139	  child.stdout.setEncoding('utf8').on('data', (d) => { stdout += d; });
140	  await new Promise((resolve, reject) => {
141	    const timer = setTimeout(() => reject(new Error('no listening line')), 5000);
142	    child.stdout.on('data', () => { if (stdout.endsWith('\n')) { clearTimeout(timer); resolve(); } });
143	    child.on('exit', () => { clearTimeout(timer); resolve(); });
144	  });
145	  return { stdout };
146	}
