12	function cleanHtml(html) {
13	  return html
14	    .replace(/<!--[\s\S]*?-->/g, (m) => ' '.repeat(m.length))
15	    .replace(/(<style\b[^>]*>)([\s\S]*?)(<\/style\s*>)/gi, (m, a, b, c) => a + ' '.repeat(b.length) + c);
16	}
17	
18	function parseAttrs(text) {
19	  const attrs = new Map();
20	  const re = /([^\s=/>]+)(?:\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'>]+)))?/g;
21	  for (const m of (text || '').matchAll(re)) {
22	    attrs.set(m[1].toLowerCase(), m[2] ?? m[3] ?? m[4] ?? '');
23	  }
24	  return attrs;
25	}
26	
27	function scanElements(html) {
28	  const out = [];
29	  const re = /<([a-zA-Z][\w-]*)(\s[^>]*)?>/g;
30	  for (const m of html.matchAll(re)) {
31	    out.push({
32	      tag: m[1].toLowerCase(),
33	      attrs: parseAttrs(m[2]),
34	      start: m.index,
35	      openEnd: m.index + m[0].length,
36	    });
37	  }
38	  return out;
39	}
40	
41	const html = cleanHtml(rawHtml);
42	const elements = scanElements(html);
43	
44	function innerOf(el) {
45	  const close = html.toLowerCase().indexOf(`</${el.tag}`, el.openEnd);
46	  assert.notEqual(close, -1, `no closing tag for <${el.tag}>`);
47	  return { inner: html.slice(el.openEnd, close), closeStart: close };
48	}
49	
50	function byId(id) {
51	  return elements.filter((e) => e.attrs.get('id') === id);
52	}
53	
54	function one(id, tag, attrs = {}) {
55	  const found = byId(id);
56	  assert.equal(found.length, 1, `id ${id} should appear exactly once`);
57	  const el = found[0];
58	  assert.equal(el.tag, tag, `#${id} tag`);
59	  for (const [k, v] of Object.entries(attrs)) assert.equal(el.attrs.get(k), v, `#${id} ${k}`);
60	  return el;
61	}
